                continue
            visited.add(abs(clause[0]))
            new_clauses = []
            for c in queue:
                if abs(c[0]) == abs(clause[1]):
                    new_clauses.append([-c[1]])
                elif abs(c[1]) == abs(clause[1]):
                    new_clauses.append([-c[0]])
            queue.extend(new_clauses)
        return len(visited)

